sections.body:
只把坐标放进 visited 会出错：玩家拿钥匙后回到同一个格子，可执行的动作已经不同。搜索状态必须包含 x、y、hasKey。下面代码先验证尺寸、符号、数量和边界，再求最短步数；无路径返回 null，格式错误抛异常。

```js
// 保存为 check-level.mjs；使用 Node.js 运行。
function shortest(rows, blockDoor = false) {
  if (!Array.isArray(rows) || rows.length !== 7 ||
      rows.some(r => typeof r !== "string" ||
        r.length !== 9 || /[^#.SKDE]/.test(r))) {
    throw new Error("需要 9×7 地图且只能含 # . S K D E");
  }
  const flat = rows.join("");
  for (const c of "SKDE") {
    if (flat.split(c).length !== 2) throw new Error(c + " 必须恰有一个");
  }
  if (rows.some(r => r[0] !== "#" || r[8] !== "#") ||
      rows[0] !== "#########" || rows[6] !== "#########") {
    throw new Error("四周必须封墙");
  }
  const start = flat.indexOf("S");
  const queue = [[start % 9, Math.floor(start / 9), false, 0]];
  const seen = new Set();
  for (let head = 0; head < queue.length; head++) {
    const [x, y, hasKey, steps] = queue[head];
    const id = [x, y, hasKey].join(",");
    if (seen.has(id)) continue;
    seen.add(id);
    if (rows[y][x] === "E") return steps;
    for (const [dx, dy] of [[1,0], [-1,0], [0,1], [0,-1]]) {
      const nx = x + dx, ny = y + dy;
      const tile = rows[ny]?.[nx];
      if (!tile || tile === "#") continue;
      if (tile === "D" && (blockDoor || !hasKey)) continue;
      queue.push([nx, ny, hasKey || tile === "K", steps + 1]);
    }
  }
  return null;
}
const map = [
  "#########",
  "#S..#..E#",
  "#.#.#.#.#",
  "#.#.D.#.#",
  "#.#.#.#.#",
  "#K..#...#",
  "#########"
];
const steps = shortest(map);
const bypass = shortest(map, true);
console.log({
  steps, bypass,
  accepted: steps !== null && bypass === null &&
    steps >= 12 && steps <= 24
});
```

第一次按正常钥匙规则搜索；第二次把 D 永久视为墙。如果第一次有路径、第二次没有路径，就说明在这套简化规则下，通关必须穿门，因此也必须先获得钥匙。accepted 还额外应用了 12–24 步的教学筛选范围。

队列按步数逐层扩展，所有移动成本相同，所以首次抵达出口的步数是最短值。hasKey 只有两个取值，这张图最多有 9×7×2 个不同状态；这是状态数上界，不是耗时测量。代码会跳过已处理状态，未针对大型地图优化。

若改成消耗钥匙、多扇可永久打开的门、推箱或动态敌人，状态就必须包含库存、门状态或箱子位置；如果格子的移动成本不同，应换成相应的最短路算法。不能直接用本函数证明这些玩法可通关。
